const item = $input.first().json;

// Check required inputs using the new Shopify column headers
// Using Description or Title as the raw info fallback
const imageUrl = item['Image Src'] || item['Image URL'] || ''; 
const rawInfo = item['Description'] || item['Title'] || ''; 

if (!imageUrl && !rawInfo) {
  throw new Error("Validation Error: Product missing Image or Description/Title!");
}

// Pass validated items safely using the new column names
return [{
  json: {
    ...item,
    validated_price: item['Price'] || item['Variant Price'] || null,
    validated_sku: item['SKU'] || item['Variant SKU'] || null,
    validated_inventory: item['Variant Inventory Qty'] || item['Inventory Qty'] || null,
    validated_weight: item['Variant Grams'] || item['Weight'] || null
  }
}];

